pseudocode:
n = arr.length; higher = new Array(n); lower = new Array(n);
higher[n-1] = true; lower[n-1] = true;
map = new TreeMap(); map.put(arr[n-1], n-1);
for (i = n - 2; i >= 0; i--) {
  higher[i] = map.ceilingEntry(arr[i]) != null ? lower[map.ceilingEntry(arr[i]).val] : false;
  lower[i] = map.floorEntry(arr[i]) != null ? higher[map.floorEntry(arr[i]).val] : false;
  map.put(arr[i], i);
}
